/* === ARCHITECTURAL RESPONSE VALIDATOR & DEPI GUARDRAIL === */
const ragData = $('Format RAG Knowledge Response').first()?.json || {};
const qwenItem = $input.first()?.json || {};
const qwenRaw = qwenItem.response;
const llmStatus = qwenRaw && !qwenItem.error && !qwenItem.errorMessage ? 'succeeded' : 'failed';
const llmLatencyMs = Number.isFinite(Number(qwenItem.total_duration)) ? Math.round(Number(qwenItem.total_duration) / 1000000) : null;
const locale = ragData.locale || 'ar';
const isAr = locale === 'ar';
const programScope = ragData.program_scope || 'DEPI';
const confidence = ragData.confidence || 'none';
const action = ragData.action || 'SAFE_DEFLECTION';
const evidenceSupported = Boolean(ragData.evidence_supported);

// 1. Out-of-Scope Initiative / Blocked Prompt Injection Direct Reply
if (ragData.is_out_of_scope) {
  const injectionBlocked = Boolean(ragData.prompt_injection_detected);
  return [{
    json: {
      status: 'out_of_scope',
      intent_handled: 'faq_query',
      program: programScope,
      category: injectionBlocked ? 'prompt_injection' : 'out_of_scope',
      reply: ragData.curated_answer,
      sources: ['وزارة الاتصالات وتكنولوجيا المعلومات (MCIT)'],
      validation: { status: injectionBlocked ? 'prompt_injection_blocked' : 'out_of_scope' },
      confidence: 'high',
      confidence_label: 'HIGH',
      guardrail_decision: injectionBlocked ? 'prompt_injection_blocked' : 'out_of_scope_deflection',
      requires_human: false,
      llm_status: 'not_needed'
    }
  }];
}

// 2. Safe Deflection Text (DEPI-focused)
const safeFallbackAR = 'شكراً على استفسارك. يختص نظامنا بالمعلومات المعتمدة لمبادرة رواد مصر الرقمية (DEPI). لم نعثر على معلومات كافية وموثقة تغطي هذا الاستفسار في قاعدة المعرفة المعتمدة حالياً. يمكنك زيارة البوابة الرسمية: https://depi.gov.eg أو التواصل مع الدعم الفني.';
const safeFallbackEN = 'Thank you for your inquiry. Our platform is specialized in the Digital Egypt Pioneers Initiative (DEPI). Sufficient verified information covering this request was not found in our current knowledge base. Please visit the official portal: https://depi.gov.eg or contact technical support.';
const safeDeflection = isAr ? safeFallbackAR : safeFallbackEN;

// 3. Evidence Gate Enforcement: If action is SAFE_DEFLECTION or confidence none or evidence not supported
if (action === 'SAFE_DEFLECTION' || confidence === 'none' || !evidenceSupported) {
  return [{
    json: {
      status: 'deflection',
      intent_handled: 'faq_query',
      program: programScope,
      category: 'general',
      reply: safeDeflection,
      sources: ['مبادرة رواد مصر الرقمية (DEPI)'],
      validation: { status: 'safe_deflected', confidence: 'none' },
      confidence: 'none',
      confidence_label: 'NONE',
      guardrail_decision: 'safe_deflection'
    }
  }];
}

// 4. Verified curated answer selected by the evidence gate (no generation needed)
if (ragData.direct_answer && ragData.curated_answer) {
  return [{
    json: {
      status: 'success',
      intent_handled: 'faq_query',
      program: programScope,
      category: ragData.top_category || 'general',
      reply: String(ragData.curated_answer).replace(/\*\*/g, '*').trim(),
      sources: [ragData.source_attribution || 'مبادرة رواد مصر الرقمية (DEPI)'],
      validation: { status: 'verified_curated_answer', confidence: confidence, relevance_score: ragData.relevance_score || 0, guardrail_decision: 'verified_curated_answer' },
      confidence: confidence,
      confidence_label: ragData.confidence_label || 'HIGH',
      guardrail_decision: 'verified_curated_answer',
      llm_status: 'not_needed',
      llm_latency_ms: null,
      retrieved_count: ragData.matched_entries || 0,
      source_url: ragData.source_url || 'https://depi.gov.eg',
      customer_message: ragData.customer_message || ''
    }
  }];
}

// 5. Parse Structured Model Response
let synthesizedAnswer = '';
let isGrounded = true;

if (qwenRaw) {
  try {
    const parsed = typeof qwenRaw === 'string' ? JSON.parse(qwenRaw.trim()) : qwenRaw;
    if (parsed && typeof parsed === 'object' && parsed.answer && parsed.answer.trim()) {
      synthesizedAnswer = parsed.answer.trim();
      isGrounded = parsed.grounded === true;
    } else {
      isGrounded = false;
    }

    // Grounding verification: Guard against self-asserted unsupported claims (e.g. NASA, guaranteed jobs)
    if (/(?:nasa|ناسا|تضمن.*وظيفة|تضمن.*التوظيف|guarantee.*job|guarantee.*employment)/i.test(synthesizedAnswer)) {
      isGrounded = false;
    }

    // A FAQ assistant has no access to applicant records, so any claim about the
    // customer's own registration/acceptance status is fabricated (paraphrases can
    // even invert official notices). Fall back to the verbatim curated answer.
    const answerNormalized = synthesizedAnswer
      .replace(/[ً-ٰٟـ]/g, '')
      .replace(/[إأآٱ]/g, 'ا');
    const personalStatusClaim =
      /(?:انك|انكم|انكي)\s+(?:غير\s+)?(?:مسجل|مسجلة|مسجلين|مقبول|مقبولة|مقبولين|مرفوض|مرفوضة|مرفوضين|مؤهل|مؤهلة|مؤهلين)/.test(answerNormalized) ||
      /تم\s+(?:تاكيد|قبول|رفض)\s+(?:انك|طلبك|تسجيلك)/.test(answerNormalized) ||
      /\byou\s+(?:are|were|have\s+been|'re)\s+(?:not\s+)?(?:registered|enrolled|accepted|rejected|eligible|ineligible|admitted|disqualified)\b/i.test(synthesizedAnswer) ||
      /\byour\s+(?:application|registration)\s+(?:has\s+been|was|is)\s+(?:accepted|rejected|approved|denied|confirmed|cancelled)\b/i.test(synthesizedAnswer);
    if (personalStatusClaim) {
      isGrounded = false;
    }

    // Generated answers must be in the customer's language.
    const arabicChars = (synthesizedAnswer.match(/[؀-ۿ]/g) || []).length;
    const latinChars = (synthesizedAnswer.match(/[A-Za-z]/g) || []).length;
    const answerIsArabic = arabicChars > latinChars;
    if (synthesizedAnswer && answerIsArabic !== isAr) {
      isGrounded = false;
    }

    const trimmedAnswer = synthesizedAnswer.trim();
    const endsOnContinuation = /[\u060C,:\uFF1A\-\u2013\u2014]\s*$/.test(trimmedAnswer);
    const belowUsefulLength = trimmedAnswer.length < (isAr ? 30 : 60);
    if (!trimmedAnswer || endsOnContinuation || belowUsefulLength) {
      isGrounded = false;
    }
  } catch (e) {
    isGrounded = false;
    synthesizedAnswer = '';
  }
} else {
  isGrounded = false;
}

// 6. Fail closed to verified curated answer if LLM failed or was ungrounded
let finalReply = synthesizedAnswer;
let guardrailDecision = 'grounded_llm';
let responseStatus = 'success';

if (llmStatus !== 'succeeded' || !synthesizedAnswer || !isGrounded) {
  if (ragData.curated_answer && (ragData.action === 'ANSWER' || confidence === 'high' || confidence === 'medium')) {
    finalReply = ragData.curated_answer;
    guardrailDecision = 'verified_faq_fallback';
    responseStatus = 'fallback';
  } else {
    finalReply = safeDeflection;
    guardrailDecision = 'safe_deflection';
    responseStatus = 'deflection';
  }
}

// Sanitization
finalReply = finalReply
  .replace(/\[(?:DEBI|DIGILIANS|COMMON|GENERAL|COMPARISON|DEPI)\]\s*/g, '')
  .replace(/سؤال:\s*/g, '')
  .replace(/إجابة:\s*/g, '')
  .replace(/^Q:\s*/gm, '')
  .replace(/^A:\s*/gm, '')
  .replace(/---\n?/g, '\n')
  .replace(/\*\*/g, '*')
  .replace(/^#+\s*/gm, '')
  .trim();

const sourceAttribution = 'مبادرة رواد مصر الرقمية (DEPI)';

return [{
  json: {
    status: responseStatus,
    intent_handled: 'faq_query',
    program: programScope,
    category: ragData.top_category || 'general',
    reply: finalReply,
    sources: [sourceAttribution],
    validation: {
      status: guardrailDecision === 'grounded_llm' ? 'passed' : guardrailDecision,
      confidence: confidence,
      relevance_score: ragData.relevance_score || 0,
      guardrail_decision: guardrailDecision
    },
    confidence: confidence,
    confidence_label: ragData.confidence_label || 'HIGH',
    guardrail_decision: guardrailDecision,
    llm_status: llmStatus,
    llm_latency_ms: llmLatencyMs,
    retrieved_count: ragData.matched_entries || 0,
    source_url: ragData.source_url || 'https://depi.gov.eg',
    customer_message: ragData.customer_message || ''
  }
}];
